    let num = 0;
    let b = readByte();
    let minus = false;
    while (b !== -1 && !(b >= 48 && b <= 57 || b === 45)) {
        b = readByte();
    }
    if (b === 45) {
        minus = true;
        b = readByte();
    }
    while (true) {
        if (b >= 48 && b <= 57) {
            num = num * 10 + (b - 48);
        } else {
            return minus ? -num : num;
        }
        b = readByte();
    }
}

function solve() {
    const n = ni();
    const s = ns();
    let r = 0;
    for (let i = 1; i < n; i++) {
        if (s[i] === s[i-1]) {
            r++;
        }
    }
    console.log(r);
}

solve();
